-- PostgreSQL 16+. Run in an empty littlesteps database. SQL is the source of truth.
BEGIN;
CREATE TABLE "Staff" (
    "StaffId"             INT GENERATED BY DEFAULT AS IDENTITY  NOT NULL CONSTRAINT PK_Staff PRIMARY KEY,
    "FullName"            VARCHAR(120)      NOT NULL,
    "Role"                VARCHAR(20)        NOT NULL
        CONSTRAINT CK_Staff_Role CHECK ("Role" IN ('Admin','Teacher','SecurityGuard','Manager')),
    "Username"            VARCHAR(50)        NOT NULL CONSTRAINT UQ_Staff_Username UNIQUE,
    "PasswordHash"        BYTEA      NOT NULL,   
    "PasswordSalt"        BYTEA      NOT NULL,   
    "MustChangePassword"  BOOLEAN                NOT NULL CONSTRAINT DF_Staff_MustChange DEFAULT (TRUE),
    "Phone"               VARCHAR(20)        NULL,
    "Photo"               BYTEA     NULL,
    "IsActive"            BOOLEAN                NOT NULL CONSTRAINT DF_Staff_IsActive DEFAULT (TRUE),
    "CreatedAt"           TIMESTAMPTZ       NOT NULL CONSTRAINT DF_Staff_CreatedAt DEFAULT (CURRENT_TIMESTAMP)
);


CREATE TABLE "Sessions" (
    "SessionId"   INT GENERATED BY DEFAULT AS IDENTITY NOT NULL CONSTRAINT PK_Sessions PRIMARY KEY,
    "StaffId"     INT               NOT NULL CONSTRAINT FK_Sessions_Staff REFERENCES "Staff"("StaffId"),
    "Token"       CHAR(64)          NOT NULL CONSTRAINT UQ_Sessions_Token UNIQUE,  
    "CreatedAt"   TIMESTAMPTZ      NOT NULL CONSTRAINT DF_Sessions_CreatedAt DEFAULT (CURRENT_TIMESTAMP),
    "ExpiresAt"   TIMESTAMPTZ      NOT NULL,
    "RevokedAt"   TIMESTAMPTZ      NULL
);

CREATE TABLE "Rooms" (
    "RoomId"  INT GENERATED BY DEFAULT AS IDENTITY NOT NULL CONSTRAINT PK_Rooms PRIMARY KEY,
    "Name"    VARCHAR(40)      NOT NULL CONSTRAINT UQ_Rooms_Name UNIQUE
);

CREATE TABLE "Classes" (
    "ClassId"     INT GENERATED BY DEFAULT AS IDENTITY NOT NULL CONSTRAINT PK_Classes PRIMARY KEY,
    "Name"        VARCHAR(20)      NOT NULL CONSTRAINT UQ_Classes_Name UNIQUE,   
    "RoomId"      INT               NOT NULL CONSTRAINT FK_Classes_Rooms REFERENCES "Rooms"("RoomId"),
    "TeacherId"   INT               NULL     CONSTRAINT FK_Classes_Teacher REFERENCES "Staff"("StaffId"),
    "Capacity"    INT               NOT NULL CONSTRAINT CK_Classes_Capacity CHECK ("Capacity" BETWEEN 1 AND 40),
    CONSTRAINT UQ_Classes_Room UNIQUE ("RoomId")            
);

CREATE UNIQUE INDEX UX_Classes_Teacher ON "Classes"("TeacherId") WHERE "TeacherId" IS NOT NULL;



CREATE TABLE "Students" (
    "StudentId"    INT GENERATED BY DEFAULT AS IDENTITY NOT NULL CONSTRAINT PK_Students PRIMARY KEY,
    "EnrolYear"    SMALLINT          NOT NULL CONSTRAINT DF_Students_EnrolYear DEFAULT (EXTRACT(YEAR FROM CURRENT_TIMESTAMP)),
    
    "StudentCode" TEXT GENERATED ALWAYS AS ('LS-' || "EnrolYear"::text || '-' || lpad("StudentId"::text, greatest(4,length("StudentId"::text)), '0')) STORED,
    "FirstName"    VARCHAR(60)      NOT NULL,
    "LastName"     VARCHAR(60)      NOT NULL,
    "DateOfBirth"  DATE              NOT NULL,
    "Gender"       CHAR(1)           NOT NULL CONSTRAINT CK_Students_Gender CHECK ("Gender" IN ('M','F')),
    "ClassId"      INT               NOT NULL CONSTRAINT FK_Students_Classes REFERENCES "Classes"("ClassId"),
    "Photo"        BYTEA    NULL,      
    
    "PhotoMissing" BOOLEAN GENERATED ALWAYS AS ("Photo" IS NULL) STORED,
    "IsActive"     BOOLEAN               NOT NULL CONSTRAINT DF_Students_IsActive DEFAULT (TRUE),
    "CreatedAt"    TIMESTAMPTZ      NOT NULL CONSTRAINT DF_Students_CreatedAt DEFAULT (CURRENT_TIMESTAMP)
);
CREATE UNIQUE INDEX UX_Students_Code ON "Students"("StudentCode");
CREATE INDEX IX_Students_Class ON "Students"("ClassId");
CREATE INDEX IX_Students_Name ON "Students"("LastName", "FirstName");

CREATE TABLE "Guardians" (
    "GuardianId"  INT GENERATED BY DEFAULT AS IDENTITY NOT NULL CONSTRAINT PK_Guardians PRIMARY KEY,
    "EmiratesId"  CHAR(18)          NOT NULL CONSTRAINT UQ_Guardians_EmiratesId UNIQUE
        
        CONSTRAINT CK_Guardians_EmiratesId CHECK ("EmiratesId" ~ '^784-[0-9]{4}-[0-9]{7}-[0-9]$'),
    "FullName"    VARCHAR(120)     NOT NULL,
    "Phone"       VARCHAR(20)       NOT NULL,
    "Photo"       BYTEA    NULL,
    "CreatedAt"   TIMESTAMPTZ      NOT NULL CONSTRAINT DF_Guardians_CreatedAt DEFAULT (CURRENT_TIMESTAMP)
);


CREATE TABLE "StudentGuardians" (
    "StudentId"     INT          NOT NULL CONSTRAINT FK_SG_Students  REFERENCES "Students"("StudentId"),
    "GuardianId"    INT          NOT NULL CONSTRAINT FK_SG_Guardians REFERENCES "Guardians"("GuardianId"),
    "Relationship"  VARCHAR(20)  NOT NULL CONSTRAINT CK_SG_Relationship CHECK ("Relationship" IN ('Father','Mother','Other')),
    CONSTRAINT PK_StudentGuardians PRIMARY KEY ("StudentId", "GuardianId")
);


CREATE TABLE "ClassTransfers" (
    "TransferId"     INT GENERATED BY DEFAULT AS IDENTITY NOT NULL CONSTRAINT PK_ClassTransfers PRIMARY KEY,
    "StudentId"      INT               NOT NULL CONSTRAINT FK_CT_Students REFERENCES "Students"("StudentId"),
    "FromClassId"    INT               NULL     CONSTRAINT FK_CT_From REFERENCES "Classes"("ClassId"),
    "ToClassId"      INT               NOT NULL CONSTRAINT FK_CT_To   REFERENCES "Classes"("ClassId"),
    "EffectiveDate"  DATE              NOT NULL,
    "Reason"         VARCHAR(200)     NOT NULL,
    "ByStaffId"      INT               NOT NULL CONSTRAINT FK_CT_Staff REFERENCES "Staff"("StaffId"),
    "CreatedAt"      TIMESTAMPTZ      NOT NULL CONSTRAINT DF_CT_CreatedAt DEFAULT (CURRENT_TIMESTAMP),
    CONSTRAINT CK_CT_Different CHECK ("FromClassId" IS NULL OR "FromClassId" <> "ToClassId")
);
CREATE INDEX IX_CT_Student ON "ClassTransfers"("StudentId", "EffectiveDate");




CREATE TABLE "AttendanceRecords" (
    "AttendanceId"     INT GENERATED BY DEFAULT AS IDENTITY NOT NULL CONSTRAINT PK_Attendance PRIMARY KEY,
    "StudentId"        INT               NOT NULL CONSTRAINT FK_Att_Students REFERENCES "Students"("StudentId"),
    "ClassId"          INT               NOT NULL CONSTRAINT FK_Att_Classes  REFERENCES "Classes"("ClassId"),  
    "AttendanceDate"   DATE              NOT NULL,
    "Status"           CHAR(1)           NOT NULL CONSTRAINT CK_Att_Status CHECK ("Status" IN ('P','A')),
    "MarkedByStaffId"  INT               NOT NULL CONSTRAINT FK_Att_Staff REFERENCES "Staff"("StaffId"),
    "MarkedAt"         TIMESTAMPTZ      NOT NULL CONSTRAINT DF_Att_MarkedAt DEFAULT (CURRENT_TIMESTAMP),
    "CorrectedAt"      TIMESTAMPTZ      NULL,   
    CONSTRAINT UQ_Att_StudentDay UNIQUE ("StudentId", "AttendanceDate")
);
CREATE INDEX IX_Att_ClassDay ON "AttendanceRecords"("ClassId", "AttendanceDate");



CREATE TABLE "Visits" (
    "VisitId"              INT GENERATED BY DEFAULT AS IDENTITY NOT NULL CONSTRAINT PK_Visits PRIMARY KEY,
    "VisitorName"          VARCHAR(120)     NOT NULL,
    "VisitorEmiratesId"    CHAR(18)          NOT NULL
        CONSTRAINT CK_Visits_EmiratesId CHECK ("VisitorEmiratesId" ~ '^784-[0-9]{4}-[0-9]{7}-[0-9]$'),
    "Reason"               VARCHAR(30)       NOT NULL
        CONSTRAINT CK_Visits_Reason CHECK ("Reason" IN ('Meeting','Delivery','Maintenance','Parent visit','Other')),
    "PersonVisited"        VARCHAR(120)     NOT NULL,
    "TimeIn"               TIMESTAMPTZ      NOT NULL CONSTRAINT DF_Visits_TimeIn DEFAULT (CURRENT_TIMESTAMP),
    "TimeOut"              TIMESTAMPTZ      NULL,      
    "RegisteredByStaffId"  INT               NOT NULL CONSTRAINT FK_Visits_Staff REFERENCES "Staff"("StaffId"),
    CONSTRAINT CK_Visits_Times CHECK ("TimeOut" IS NULL OR "TimeOut" >= "TimeIn")
);
CREATE INDEX IX_Visits_TimeIn ON "Visits"("TimeIn");


CREATE TABLE "EarlyExits" (
    "EarlyExitId"          INT GENERATED BY DEFAULT AS IDENTITY NOT NULL CONSTRAINT PK_EarlyExits PRIMARY KEY,
    "StudentId"            INT               NOT NULL CONSTRAINT FK_EE_Students  REFERENCES "Students"("StudentId"),
    "PresentedEmiratesId"  CHAR(18)          NOT NULL,                 
    "GuardianId"           INT               NULL     CONSTRAINT FK_EE_Guardians REFERENCES "Guardians"("GuardianId"),
    "Authorized"           BOOLEAN               NOT NULL,
    "Reason"               VARCHAR(30)       NULL
        CONSTRAINT CK_EE_Reason CHECK ("Reason" IN ('Medical appointment','Family reason','Feeling unwell','Other')),
    "OccurredAt"           TIMESTAMPTZ      NOT NULL CONSTRAINT DF_EE_OccurredAt DEFAULT (CURRENT_TIMESTAMP),
    "GuardStaffId"         INT               NOT NULL CONSTRAINT FK_EE_Staff REFERENCES "Staff"("StaffId"),
    
    CONSTRAINT CK_EE_Consistent CHECK (
        ("Authorized" = TRUE AND "GuardianId" IS NOT NULL AND "Reason" IS NOT NULL) OR
        ("Authorized" = FALSE AND "GuardianId" IS NULL))
);
CREATE INDEX IX_EE_Student ON "EarlyExits"("StudentId", "OccurredAt");



CREATE TABLE "AuditEntries" (
    "AuditId"     BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL CONSTRAINT PK_AuditEntries PRIMARY KEY,
    "OccurredAt"  TIMESTAMPTZ         NOT NULL CONSTRAINT DF_Audit_OccurredAt DEFAULT (CURRENT_TIMESTAMP),
    "StaffId"     INT                  NULL CONSTRAINT FK_Audit_Staff REFERENCES "Staff"("StaffId"),  
    "Username"    VARCHAR(50)          NULL,
    "Area"        VARCHAR(20)          NOT NULL
        CONSTRAINT CK_Audit_Area CHECK ("Area" IN ('Access','Staff','Classes','Students','Guardians','Attendance','Gate control')),
    "Action"      VARCHAR(40)          NOT NULL,
    "Details"     VARCHAR(400)        NULL,
    "Result"      VARCHAR(12)          NOT NULL
        CONSTRAINT CK_Audit_Result CHECK ("Result" IN ('OK','Refused','Incomplete')),
    "EntityType"  VARCHAR(30)          NULL,
    "EntityId"    INT                  NULL
);
CREATE INDEX IX_Audit_OccurredAt ON "AuditEntries"("OccurredAt" DESC);


-- Preserve the audit trail even when maintenance is performed directly in SQL.
CREATE FUNCTION protect_audit() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION 'Audit entries are read-only.'; END $$;
CREATE TRIGGER audit_read_only BEFORE UPDATE OR DELETE OR TRUNCATE ON "AuditEntries"
FOR EACH STATEMENT EXECUTE FUNCTION protect_audit();

-- Serialise occupancy changes so concurrent enrolments cannot overfill a class.
CREATE FUNCTION protect_capacity() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE maximum integer; occupied integer;
BEGIN
 IF NOT NEW."IsActive" THEN RETURN NEW; END IF;
 SELECT "Capacity" INTO maximum FROM "Classes" WHERE "ClassId"=NEW."ClassId" FOR UPDATE;
 SELECT count(*) INTO occupied FROM "Students" WHERE "ClassId"=NEW."ClassId" AND "IsActive" AND "StudentId"<>NEW."StudentId";
 IF occupied>=maximum THEN RAISE EXCEPTION 'Class is full.' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER students_capacity BEFORE INSERT OR UPDATE OF "ClassId", "IsActive" ON "Students"
FOR EACH ROW EXECUTE FUNCTION protect_capacity();
CREATE FUNCTION protect_class() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF NEW."TeacherId" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM "Staff" WHERE "StaffId"=NEW."TeacherId" AND "Role"='Teacher' AND "IsActive") THEN
 RAISE EXCEPTION 'An active teacher is required.' USING ERRCODE='23514'; END IF;
 IF NEW."Capacity" < (SELECT count(*) FROM "Students" WHERE "ClassId"=NEW."ClassId" AND "IsActive") THEN
 RAISE EXCEPTION 'Capacity is below current enrolment.' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER classes_rules BEFORE INSERT OR UPDATE ON "Classes" FOR EACH ROW EXECUTE FUNCTION protect_class();

COMMIT;
